package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFile *os.File
var dateScanner *bufio.Scanner

func truncVal(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// COBOL truncation keeps low-order digits, for positive it's modulo
	// For safety handle negative by preserving sign low-order
	if v >= 0 {
		return v % mod
	}
	// negative: keep low-order digits with sign
	av := -v
	av = av % mod
	return -av
}

func fmt9(v int64, width int) string {
	// display zero-padded to width, high-order digits dropped already via trunc
	// For negative, COBOL would show sign? Not needed for this program.
	// We just format with zero pad.
	if v < 0 {
		// format absolute then prefix minus, zero pad
		av := -v
		s := fmt.Sprintf("%0*d", width, av)
		// if width includes sign? Simplified: prepend minus
		// But not needed in tests.
		return "-" + s
	}
	return fmt.Sprintf("%0*d", width, v)
}

func parseDigits(s string, digits int) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// Keep only digits and optional leading sign; COBOL numeric fields should be digits only
	// If there are non-digit chars, try to parse as integer ignoring spaces
	// Use Atoi; if fails, extract digits
	n, err := strconv.ParseInt(s, 10, 64)
	if err == nil {
		return truncVal(n, digits)
	}
	// fallback: extract digits
	filt := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			filt += string(ch)
		}
	}
	if filt == "" {
		return 0
	}
	n2, err2 := strconv.ParseInt(filt, 10, 64)
	if err2 != nil {
		return 0
	}
	return truncVal(n2, digits)
}

func padRight(s string, length int) string {
	if len(s) >= length {
		return s[:length]
	}
	return s + strings.Repeat(" ", length-len(s))
}

// keep decimal import used
var _ = decimal.NewFromInt(0)

func isInputDone() bool {
	return WsEofFlag == "Y"
}
func isLeap() bool {
	return WsLeapFlag == "Y"
}

// Paragraph functions

func READPARA() {
	if dateScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if dateScanner.Scan() {
		line := dateScanner.Text()
		// Scanner strips \r but keep; remove trailing \r if present
		line = strings.TrimSuffix(line, "\r")
		// Pad to record length 12 if shorter
		if len(line) < 12 {
			line = padRight(line, 12)
		} else if len(line) > 12 {
			line = line[:12]
		}
		// parse
		DateRecVar.DtId = line[0:4]
		DateRecVar.DtYyyy = parseDigits(line[4:8], 4)
		DateRecVar.DtMm = parseDigits(line[8:10], 2)
		DateRecVar.DtDd = parseDigits(line[10:12], 2)
	} else {
		WsEofFlag = "Y"
	}
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	// etc.
	// Integer division
	if 4 != 0 {
		q := DateRecVar.DtYyyy / 4
		r := DateRecVar.DtYyyy % 4
		WsQ = truncVal(q, 4)
		WsR4 = truncVal(r, 3)
	}
	if 100 != 0 {
		q := DateRecVar.DtYyyy / 100
		r := DateRecVar.DtYyyy % 100
		WsQ = truncVal(q, 4)
		WsR100 = truncVal(r, 3)
	}
	if 400 != 0 {
		q := DateRecVar.DtYyyy / 400
		r := DateRecVar.DtYyyy % 400
		WsQ = truncVal(q, 4)
		WsR400 = truncVal(r, 3)
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecVar.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = truncVal(29, 2)
		} else {
			WsMaxDay = truncVal(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncVal(30, 2)
	default:
		WsMaxDay = truncVal(31, 2)
	}
}

func PROCESSPARA() {
	LEAPPARA()
	if DateRecVar.DtMm < 1 || DateRecVar.DtMm > 12 {
		WsBadMonth = truncVal(WsBadMonth+1, 2)
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		fmt.Println(DateRecVar.DtId + " BAD MONTH " + fmt9(DateRecVar.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = truncVal(WsBadDay+1, 2)
			fmt.Println(DateRecVar.DtId + " BAD DAY " + fmt9(DateRecVar.DtDd, 2) + " MAX " + fmt9(WsMaxDay, 2))
		} else {
			WsValid = truncVal(WsValid+1, 2)
			fmt.Println(DateRecVar.DtId + " VALID " + fmt9(DateRecVar.DtYyyy, 4) + "-" + fmt9(DateRecVar.DtMm, 2) + "-" + fmt9(DateRecVar.DtDd, 2))
		}
	}
	READPARA()
}

func MAINPARA() {
	f, err := os.Open("input.dat")
	if err != nil {
		// treat as empty file
		WsEofFlag = "Y"
		// Still need to display summary
		fmt.Println("VALID: " + fmt9(WsValid, 2) + " BAD MONTH: " + fmt9(WsBadMonth, 2) + " BAD DAY: " + fmt9(WsBadDay, 2))
		return
	}
	dateFile = f
	defer f.Close()
	dateScanner = bufio.NewScanner(f)
	// Allow long lines
	// Use default split

	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE DATE-FILE (deferred)
	fmt.Println("VALID: " + fmt9(WsValid, 2) + " BAD MONTH: " + fmt9(WsBadMonth, 2) + " BAD DAY: " + fmt9(WsBadDay, 2))
}

func main() {
	MAINPARA()
}
